window.blogDetail = {"blogId":1784465985,"blogType":3,"pubTime":"2026-07-19 20:59","sLastModifyTime":"2026-07-20 13:19","lastModifyTime":1784524794,"cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"牝鸡司晨?那不过是一个女子被命运逼出的野心——游戏里的元照,史书里的则天,至尊帝位下的两种无奈","commentNum":0,"effect1":8454657,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"编者按<br/>这是我的《盛世天下》通关手记。<br/>通关之后,我原本想以历史考据加评论的方式,写一下自己对这款游戏的看法。游戏把武则天塑造成一个主动夺权、逆天改命的觉醒者,可这条逻辑线跟史实对照下来,我总觉得有些地方说不通。后来又想,既然游戏已经影视化了,那何不干脆写一个女主的剧本,让自己代入女主的视角,代入历史上真正的武则天,重新看待这段历史,去体会她的心境和她的人生。于是写着写着,这份思考...","img":[{"url":"https://mmbiz.qpic.cn/sz_mmbiz_png/BibhN01hM4jjoTVal4ljGb8icheiaqkeqeZEXnxAsuSB5BowxuhE9tvTjibRWn59CvfvmrBMclOQ3HXhoaguhFFmJMA44INBVDR7kr9nFR39Cqk/0?wx_fmt=png&from=appmsg","custom_url":"images/7AF07984"}],"artype":1,"arUins":"","blogid":1784465985,"voteids":0,"pubtime":1784524794,"replynum":0,"category":"个人日记","effect":8454657,"exblogtype":3,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":81177,"lp_style":16843520,"lp_flag":0,"lp_topvalue":0,"orguin":619774944,"orgblogid":1784465985,"mention_uins":[],"attach":[],"comments":[],"html":"","custom_title":"牝鸡司晨?那不过是一个女子被命运逼出的野心——游戏里的元照,史书里的则天,至尊帝位下的两种无奈","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1784465985"}